for name in ['PROOF.md','OPEN.md','TERM-TABLE.md','REQUIREMENT-MAP.md','HANDOFF.md','SECURITY-CRITERION.md']:
    assert not (B/name).exists();shutil.copy2(X/name,B/name)
def replace(name,old,new):
    p=X/name;t=p.read_text(encoding='utf8');assert t.count(old)==1,(name,old)
    p.write_text(t.replace(old,new,1),encoding='utf8')
